BEGIN;
SELECT next_vlan_id FROM vlan_pool WHERE pool_name = 'production' FOR UPDATE;
UPDATE vlan_pool SET next_vlan_id = next_vlan_id + 1 WHERE pool_name = 'production';
COMMIT;
