Normalize the output using Python's `re` (regex) and `json` modules to parse and standardize fields like interface name, description, and vendor-specific syntax into a structured dictionary, then convert it to JSON for consistency.

```python
import re
import json

def normalize_interface_desc(output, vendor):
    interfaces = []
    if vendor.lower() == "cisco":
        pattern = r"(\w+)\s+(\S.*)"
        for line in output.split('\n'):
            match = re.match(pattern, line.strip())
            if match:
                interfaces.append({
                    "interface": match.group(1),
                    "description": match.group(2),
                    "vendor": vendor
                })
    elif vendor.lower() == "juniper":
        pattern = r"(\w+)\s+(\S.*)"
        for line in output.split('\n'):
            match = re.match(pattern, line.strip())
            if match:
                interfaces.append({
                    "interface": match.group(1),
                    "description": match.group(2),
                    "vendor": vendor
                })
    return json.dumps(interfaces, indent=2)

# Example usage:
cisco_output = """
Gi0/1    Some description
Gi0/2    Another description
"""
juniper_output = """
ge-0/0/1  Some description
ge-0/0/2  Another description
"""
print(normalize_interface_desc(cisco_output, "Cisco"))
print(normalize_interface_desc(juniper_output, "Juniper"))
